-- 0007_add_devices_device — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- device: one camera, box or sensor in the registry (E4 AC1, data-model.md "Device"). Every device sits on a
-- site of its client; client_id is carried for RLS and must match the site's (composite foreign key).
-- Staff see all rows; a client sees its own rows marked visibility = 'client' (none until the client portal);
-- partners see nothing until a policy links rows to their assigned jobs or sites.
ALTER TABLE site ADD CONSTRAINT site_id_client UNIQUE (id, client_id);

CREATE TABLE device (
  id             uuid PRIMARY KEY,
  client_id      uuid NOT NULL,
  site_id        uuid NOT NULL,
  sn             text NOT NULL CHECK (sn <> '' AND sn = btrim(sn)),
  -- Stored as AA:BB:CC:DD:EE:FF; the register command normalises other spellings.
  mac            text CHECK (mac ~ '^[0-9A-F]{2}(:[0-9A-F]{2}){5}$'),
  model          text NOT NULL CHECK (model <> ''),
  firmware       text,
  switch_name    text,
  switch_port    text,
  ip             inet,
  status         text NOT NULL DEFAULT 'planned' CHECK (status IN
                   ('planned', 'shipped', 'received', 'installed', 'online', 'calibrated', 'faulty', 'lost')),
  replaced_by_id uuid REFERENCES device (id),
  visibility     text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at     timestamptz NOT NULL DEFAULT now(),
  archived_at    timestamptz,
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX device_client ON device (client_id);
CREATE INDEX device_site ON device (site_id);
-- R6 (rules.md, P0): the same SN or MAC never in two active records. The rule devices/duplicate-sn-mac gives
-- the readable error at save; these indexes are the backstop for races and imports.
CREATE UNIQUE INDEX device_active_sn ON device (upper(sn)) WHERE archived_at IS NULL;
CREATE UNIQUE INDEX device_active_mac ON device (mac) WHERE archived_at IS NULL AND mac IS NOT NULL;

ALTER TABLE device ENABLE ROW LEVEL SECURITY;
CREATE POLICY device_internal ON device FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY device_client_read ON device FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON device TO ocs_app;
